package com.pranit.productsupport.worker;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.UUID;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;
@Component public class NotificationConsumer {private static final Logger log=LoggerFactory.getLogger(NotificationConsumer.class);private final ObjectMapper mapper;private final JdbcTemplate jdbc;public NotificationConsumer(ObjectMapper m,JdbcTemplate j){mapper=m;jdbc=j;}
 @KafkaListener(topics="${app.kafka.events-topic}") public void consume(String raw)throws Exception{JsonNode envelope=mapper.readTree(raw);String eventId=envelope.path("eventId").asText();String eventType=envelope.path("eventType").asText("Unknown");if(eventId.isBlank())throw new IllegalArgumentException("Event does not contain eventId");int inserted=jdbc.update("INSERT IGNORE INTO processed_events(event_id, processed_at) VALUES (?, UTC_TIMESTAMP(6))",eventId);if(inserted==0){log.info("Skipping duplicate event {}",eventId);return;}JsonNode payload=envelope.path("payload");switch(eventType){case "TicketCreated" -> log.info("[NOTIFICATION DEMO] Ticket {} created for customer {} and product {}",payload.path("ticketId").asText(),payload.path("customerId").asText(),payload.path("productName").asText());case "TicketStatusChanged" -> log.info("[NOTIFICATION DEMO] Ticket {} changed status {} -> {}",payload.path("ticketId").asText(),payload.path("oldStatus").asText(),payload.path("newStatus").asText());case "TicketAssigned" -> log.info("[NOTIFICATION DEMO] Ticket {} assigned to support user {}",payload.path("ticketId").asText(),payload.path("assignedTo").asText());case "PaymentCaptured" -> log.info("[NOTIFICATION DEMO] Payment {} captured for quote {}",payload.path("paymentId").asText(),payload.path("quoteId").asText());case "DuplicatePaymentCaptureDetected" -> log.error("[PAYMENT RECONCILIATION] Possible duplicate capture for payment {} and quote {}; investigate and refund if confirmed",payload.path("paymentId").asText(),payload.path("quoteId").asText());default -> log.info("No notification handler for event type {}",eventType);}}
}
